/**
 *  ----------------------------------------------------------------------
 *  Top-level Type value, enabling extensible type-specific metadata. We can
 *  add new logical types to Type without breaking backwards compatibility
 */
export type Type = Null | Int | FloatingPoint | Binary | Utf8 | Bool | Decimal | Date | Time | Timestamp | Interval | List | Struct_ | Union | FixedSizeBinary | FixedSizeList | Map | Duration | LargeBinary | LargeUtf8 | LargeList | RunEndEncoded | BinaryView | Utf8View | ListView | LargeListView;

