/**
 *  ----------------------------------------------------------------------
 *  A Buffer represents a single contiguous memory segment
 */
export class Buffer {
/**
 *  The absolute length (in bytes) of the memory buffer. The memory is found
 *  from offset (inclusive) to offset + length (non-inclusive). When building
 *  messages using the encapsulated IPC message, padding bytes may be written
 *  after a buffer, but such padding bytes do not need to be accounted for in
 *  the size here.
 */
  private _length!: bigint;

/**
 *  The relative offset into the shared memory page where the bytes for this
 *  buffer starts
 */
  private _offset!: bigint;

  constructor(arg?: FbsBuffer) {
    if (arg instanceof FbsBuffer) {
      this._initFromFbs(arg);
    } else {
      this._length = BigInt(0);
      this._offset = BigInt(0);
    }
  }

  private _initFromFbs(fbs: FbsBuffer): void {
    this._length = fbs.length();
    this._offset = fbs.offset();
  }

  get length(): bigint {
    return this._length;
  }

  set length(value: bigint) {
    this._length = value;
  }

  get offset(): bigint {
    return this._offset;
  }

  set offset(value: bigint) {
    this._offset = value;
  }

  toFbsT(): FbsBufferT {
    const t = new FbsBufferT();
    t.length = this._length;
    t.offset = this._offset;
    return t;
  }

}

export class DictionaryEncoding {
  private _dictionaryKind!: number;

/**
 *  The known dictionary id in the application where this data is used. In
 *  the file or streaming formats, the dictionary ids are found in the
 *  DictionaryBatch messages
 */
  private _id!: bigint;

/**
 *  The dictionary indices are constrained to be non-negative integers. If
 *  this field is null, the indices must be signed int32. To maximize
 *  cross-language compatibility and performance, implementations are
 *  recommended to prefer signed integer types over unsigned integer types
 *  and to avoid uint64 indices unless they are required by an application.
 */
  private _indexType!: Int | null;

/**
 *  By default, dictionaries are not ordered, or the order does not have
 *  semantic meaning. In some statistical, applications, dictionary-encoding
 *  is used to represent ordered categorical data, and we provide a way to
 *  preserve that metadata here
 */
  private _isOrdered!: boolean;

  constructor(arg?: FbsDictionaryEncoding | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsDictionaryEncoding.getSizePrefixedRootAsDictionaryEncoding(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsDictionaryEncoding) {
      this._initFromFbs(arg);
    } else {
      this._dictionaryKind = 0;
      this._id = BigInt(0);
      this._indexType = null;
      this._isOrdered = false;
    }
  }

  private _initFromFbs(fbs: FbsDictionaryEncoding): void {
    this._dictionaryKind = fbs.dictionaryKind();
    this._id = fbs.id();
    const indexTypeVal = fbs.indexType();
    this._indexType = indexTypeVal ? new Int(indexTypeVal) : null;
    this._isOrdered = fbs.isOrdered();
  }

  get dictionaryKind(): number {
    return this._dictionaryKind;
  }

  set dictionaryKind(value: number) {
    this._dictionaryKind = value;
  }

  get id(): bigint {
    return this._id;
  }

  set id(value: bigint) {
    this._id = value;
  }

  get indexType(): Int | null {
    return this._indexType;
  }

  set indexType(value: Int | null) {
    this._indexType = value;
  }

  get isOrdered(): boolean {
    return this._isOrdered;
  }

  set isOrdered(value: boolean) {
    this._isOrdered = value;
  }

  toFbsT(): FbsDictionaryEncodingT {
    const t = new FbsDictionaryEncodingT();
    t.dictionaryKind = this._dictionaryKind;
    t.id = this._id;
    t.indexType = this._indexType ? this._indexType.toFbsT() : null;
    t.isOrdered = this._isOrdered;
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

/**
 *  ----------------------------------------------------------------------
 *  A field represents a named column in a record / row batch or child of a
 *  nested type.
 */
export class Field {
/**
 *  children apply only to nested data types like Struct, List and Union. For
 *  primitive types children will have length 0.
 */
  private _children!: Field[] | null;

/**
 *  User-defined metadata
 */
  private _customMetadata!: KeyValue[] | null;

/**
 *  Present only if the field is dictionary encoded.
 */
  private _dictionary!: DictionaryEncoding | null;

/**
 *  Name is not required, in i.e. a List
 */
  private _name!: string | null;

/**
 *  Whether or not this field can contain nulls. Should be true in general.
 */
  private _nullable!: boolean;

/**
 *  This is the type of the decoded value if the field is dictionary encoded.
 */
  private _type!: Type | null;

  constructor(arg?: FbsField | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsField.getSizePrefixedRootAsField(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsField) {
      this._initFromFbs(arg);
    } else {
      this._children = null;
      this._customMetadata = null;
      this._dictionary = null;
      this._name = null;
      this._nullable = false;
      this._type = null;
    }
  }

  private _initFromFbs(fbs: FbsField): void {
    if (fbs.childrenLength() > 0) {
      this._children = Array.from({ length: fbs.childrenLength() }, (_, i) => {
        const item = fbs.children(i);
        return item ? new Field(item) : new Field();
      });
    } else {
      this._children = null;
    }
    if (fbs.customMetadataLength() > 0) {
      this._customMetadata = Array.from({ length: fbs.customMetadataLength() }, (_, i) => {
        const item = fbs.customMetadata(i);
        return item ? new KeyValue(item) : new KeyValue();
      });
    } else {
      this._customMetadata = null;
    }
    const dictionaryVal = fbs.dictionary();
    this._dictionary = dictionaryVal ? new DictionaryEncoding(dictionaryVal) : null;
    this._name = fbs.name();
    this._nullable = fbs.nullable();
    const typeTy = fbs.typeType();
    if (typeTy === FbsType.Null) {
      const typeFbsVal = fbs.type(new FbsNull());
      this._type = typeFbsVal ? new Null(typeFbsVal) : null;
    } else if (typeTy === FbsType.Int) {
      const typeFbsVal = fbs.type(new FbsInt());
      this._type = typeFbsVal ? new Int(typeFbsVal) : null;
    } else if (typeTy === FbsType.FloatingPoint) {
      const typeFbsVal = fbs.type(new FbsFloatingPoint());
      this._type = typeFbsVal ? new FloatingPoint(typeFbsVal) : null;
    } else if (typeTy === FbsType.Binary) {
      const typeFbsVal = fbs.type(new FbsBinary());
      this._type = typeFbsVal ? new Binary(typeFbsVal) : null;
    } else if (typeTy === FbsType.Utf8) {
      const typeFbsVal = fbs.type(new FbsUtf8());
      this._type = typeFbsVal ? new Utf8(typeFbsVal) : null;
    } else if (typeTy === FbsType.Bool) {
      const typeFbsVal = fbs.type(new FbsBool());
      this._type = typeFbsVal ? new Bool(typeFbsVal) : null;
    } else if (typeTy === FbsType.Decimal) {
      const typeFbsVal = fbs.type(new FbsDecimal());
      this._type = typeFbsVal ? new Decimal(typeFbsVal) : null;
    } else if (typeTy === FbsType.Date) {
      const typeFbsVal = fbs.type(new FbsDate());
      this._type = typeFbsVal ? new Date(typeFbsVal) : null;
    } else if (typeTy === FbsType.Time) {
      const typeFbsVal = fbs.type(new FbsTime());
      this._type = typeFbsVal ? new Time(typeFbsVal) : null;
    } else if (typeTy === FbsType.Timestamp) {
      const typeFbsVal = fbs.type(new FbsTimestamp());
      this._type = typeFbsVal ? new Timestamp(typeFbsVal) : null;
    } else if (typeTy === FbsType.Interval) {
      const typeFbsVal = fbs.type(new FbsInterval());
      this._type = typeFbsVal ? new Interval(typeFbsVal) : null;
    } else if (typeTy === FbsType.List) {
      const typeFbsVal = fbs.type(new FbsList());
      this._type = typeFbsVal ? new List(typeFbsVal) : null;
    } else if (typeTy === FbsType.Struct_) {
      const typeFbsVal = fbs.type(new FbsStruct_());
      this._type = typeFbsVal ? new Struct_(typeFbsVal) : null;
    } else if (typeTy === FbsType.Union) {
      const typeFbsVal = fbs.type(new FbsUnion());
      this._type = typeFbsVal ? new Union(typeFbsVal) : null;
    } else if (typeTy === FbsType.FixedSizeBinary) {
      const typeFbsVal = fbs.type(new FbsFixedSizeBinary());
      this._type = typeFbsVal ? new FixedSizeBinary(typeFbsVal) : null;
    } else if (typeTy === FbsType.FixedSizeList) {
      const typeFbsVal = fbs.type(new FbsFixedSizeList());
      this._type = typeFbsVal ? new FixedSizeList(typeFbsVal) : null;
    } else if (typeTy === FbsType.Map) {
      const typeFbsVal = fbs.type(new FbsMap());
      this._type = typeFbsVal ? new Map(typeFbsVal) : null;
    } else if (typeTy === FbsType.Duration) {
      const typeFbsVal = fbs.type(new FbsDuration());
      this._type = typeFbsVal ? new Duration(typeFbsVal) : null;
    } else if (typeTy === FbsType.LargeBinary) {
      const typeFbsVal = fbs.type(new FbsLargeBinary());
      this._type = typeFbsVal ? new LargeBinary(typeFbsVal) : null;
    } else if (typeTy === FbsType.LargeUtf8) {
      const typeFbsVal = fbs.type(new FbsLargeUtf8());
      this._type = typeFbsVal ? new LargeUtf8(typeFbsVal) : null;
    } else if (typeTy === FbsType.LargeList) {
      const typeFbsVal = fbs.type(new FbsLargeList());
      this._type = typeFbsVal ? new LargeList(typeFbsVal) : null;
    } else if (typeTy === FbsType.RunEndEncoded) {
      const typeFbsVal = fbs.type(new FbsRunEndEncoded());
      this._type = typeFbsVal ? new RunEndEncoded(typeFbsVal) : null;
    } else if (typeTy === FbsType.BinaryView) {
      const typeFbsVal = fbs.type(new FbsBinaryView());
      this._type = typeFbsVal ? new BinaryView(typeFbsVal) : null;
    } else if (typeTy === FbsType.Utf8View) {
      const typeFbsVal = fbs.type(new FbsUtf8View());
      this._type = typeFbsVal ? new Utf8View(typeFbsVal) : null;
    } else if (typeTy === FbsType.ListView) {
      const typeFbsVal = fbs.type(new FbsListView());
      this._type = typeFbsVal ? new ListView(typeFbsVal) : null;
    } else if (typeTy === FbsType.LargeListView) {
      const typeFbsVal = fbs.type(new FbsLargeListView());
      this._type = typeFbsVal ? new LargeListView(typeFbsVal) : null;
    } else {
      this._type = null;
    }
  }

  get children(): Field[] | null {
    return this._children;
  }

  set children(value: Field[] | null) {
    this._children = value;
  }

  get customMetadata(): KeyValue[] | null {
    return this._customMetadata;
  }

  set customMetadata(value: KeyValue[] | null) {
    this._customMetadata = value;
  }

  get dictionary(): DictionaryEncoding | null {
    return this._dictionary;
  }

  set dictionary(value: DictionaryEncoding | null) {
    this._dictionary = value;
  }

  get name(): string | null {
    return this._name;
  }

  set name(value: string | null) {
    this._name = value;
  }

  get nullable(): boolean {
    return this._nullable;
  }

  set nullable(value: boolean) {
    this._nullable = value;
  }

  get type(): Type | null {
    return this._type;
  }

  set type(value: Type | null) {
    this._type = value;
  }

  toFbsT(): FbsFieldT {
    const t = new FbsFieldT();
    t.children = this._children ? this._children.map(item => item.toFbsT()) : [];
    t.customMetadata = this._customMetadata ? this._customMetadata.map(item => item.toFbsT()) : [];
    t.dictionary = this._dictionary ? this._dictionary.toFbsT() : null;
    t.name = this._name;
    t.nullable = this._nullable;
    if (this._type instanceof Null) {
      t.typeType = FbsType.Null;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Int) {
      t.typeType = FbsType.Int;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof FloatingPoint) {
      t.typeType = FbsType.FloatingPoint;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Binary) {
      t.typeType = FbsType.Binary;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Utf8) {
      t.typeType = FbsType.Utf8;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Bool) {
      t.typeType = FbsType.Bool;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Decimal) {
      t.typeType = FbsType.Decimal;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Date) {
      t.typeType = FbsType.Date;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Time) {
      t.typeType = FbsType.Time;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Timestamp) {
      t.typeType = FbsType.Timestamp;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Interval) {
      t.typeType = FbsType.Interval;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof List) {
      t.typeType = FbsType.List;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Struct_) {
      t.typeType = FbsType.Struct_;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Union) {
      t.typeType = FbsType.Union;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof FixedSizeBinary) {
      t.typeType = FbsType.FixedSizeBinary;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof FixedSizeList) {
      t.typeType = FbsType.FixedSizeList;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Map) {
      t.typeType = FbsType.Map;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Duration) {
      t.typeType = FbsType.Duration;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof LargeBinary) {
      t.typeType = FbsType.LargeBinary;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof LargeUtf8) {
      t.typeType = FbsType.LargeUtf8;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof LargeList) {
      t.typeType = FbsType.LargeList;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof RunEndEncoded) {
      t.typeType = FbsType.RunEndEncoded;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof BinaryView) {
      t.typeType = FbsType.BinaryView;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof Utf8View) {
      t.typeType = FbsType.Utf8View;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof ListView) {
      t.typeType = FbsType.ListView;
      t.type = this._type.toFbsT();
    } else if (this._type instanceof LargeListView) {
      t.typeType = FbsType.LargeListView;
      t.type = this._type.toFbsT();
    }
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

/**
 *  ----------------------------------------------------------------------
 *  user defined key value pairs to add custom metadata to arrow
 *  key namespacing is the responsibility of the user
 */
export class KeyValue {
  private _key!: string | null;

  private _value!: string | null;

  constructor(arg?: FbsKeyValue | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsKeyValue.getSizePrefixedRootAsKeyValue(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsKeyValue) {
      this._initFromFbs(arg);
    } else {
      this._key = null;
      this._value = null;
    }
  }

  private _initFromFbs(fbs: FbsKeyValue): void {
    this._key = fbs.key();
    this._value = fbs.value();
  }

  get key(): string | null {
    return this._key;
  }

  set key(value: string | null) {
    this._key = value;
  }

  get value(): string | null {
    return this._value;
  }

  set value(value: string | null) {
    this._value = value;
  }

  toFbsT(): FbsKeyValueT {
    const t = new FbsKeyValueT();
    t.key = this._key;
    t.value = this._value;
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}

/**
 *  ----------------------------------------------------------------------
 *  A Schema describes the columns in a row batch
 */
export class Schema {
  private _customMetadata!: KeyValue[] | null;

/**
 *  endianness of the buffer
 *  it is Little Endian by default
 *  if endianness doesn't match the underlying system then the vectors need to be converted
 */
  private _endianness!: number;

/**
 *  Features used in the stream/file.
 */
  private _features!: bigint[] | null;

  private _fields!: Field[] | null;

  constructor(arg?: FbsSchema | Uint8Array) {
    if (arg instanceof Uint8Array) {
      const buf = new flatbuffers.ByteBuffer(arg);
      const fbs = FbsSchema.getSizePrefixedRootAsSchema(buf);
      this._initFromFbs(fbs);
    } else if (arg instanceof FbsSchema) {
      this._initFromFbs(arg);
    } else {
      this._customMetadata = null;
      this._endianness = 0;
      this._features = null;
      this._fields = null;
    }
  }

  private _initFromFbs(fbs: FbsSchema): void {
    if (fbs.customMetadataLength() > 0) {
      this._customMetadata = Array.from({ length: fbs.customMetadataLength() }, (_, i) => {
        const item = fbs.customMetadata(i);
        return item ? new KeyValue(item) : new KeyValue();
      });
    } else {
      this._customMetadata = null;
    }
    this._endianness = fbs.endianness();
    if (fbs.featuresLength() > 0) {
      this._features = Array.from({ length: fbs.featuresLength() }, (_, i) => fbs.features(i)!);
    } else {
      this._features = null;
    }
    if (fbs.fieldsLength() > 0) {
      this._fields = Array.from({ length: fbs.fieldsLength() }, (_, i) => {
        const item = fbs.fields(i);
        return item ? new Field(item) : new Field();
      });
    } else {
      this._fields = null;
    }
  }

  get customMetadata(): KeyValue[] | null {
    return this._customMetadata;
  }

  set customMetadata(value: KeyValue[] | null) {
    this._customMetadata = value;
  }

  get endianness(): number {
    return this._endianness;
  }

  set endianness(value: number) {
    this._endianness = value;
  }

  get features(): bigint[] | null {
    return this._features;
  }

  set features(value: bigint[] | null) {
    this._features = value;
  }

  get fields(): Field[] | null {
    return this._fields;
  }

  set fields(value: Field[] | null) {
    this._fields = value;
  }

  toFbsT(): FbsSchemaT {
    const t = new FbsSchemaT();
    t.customMetadata = this._customMetadata ? this._customMetadata.map(item => item.toFbsT()) : [];
    t.endianness = this._endianness;
    t.features = this._features ?? [];
    t.fields = this._fields ? this._fields.map(item => item.toFbsT()) : [];
    return t;
  }

  toBytes(): Uint8Array {
    const builder = new flatbuffers.Builder();
    const offset = this.toFbsT().pack(builder);
    builder.finishSizePrefixed(offset);
    return builder.asUint8Array();
  }
}
